  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks unite quantum control with an exceptionally consequential advance in precision measurement.",
        "attribution": "Katori conceived the decisive magic-wavelength clock architecture, while Ye made foundational experimental advances and broad realization possible.",
        "maturity": "The method is mature, reproducible internationally, and has set the frontier for optical timekeeping.",
        "uncertainties": [
          "The proper division of credit among the wider optical-clock community requires careful historical review."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B046",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made the interaction of individual artificial atoms and microwave photons controllable on a chip, opening a genuinely new experimental quantum-optics regime.",
        "attribution": "Blais provided the central theoretical formulation; Wallraff and Schoelkopf led landmark experimental realization.",
        "maturity": "Its basic physics has been repeatedly confirmed and is now a durable platform for quantum optics and information.",
        "uncertainties": [
          "The field has many indispensable contributors, so the limited laureate allocation is difficult."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Peter W. Shor",
        "Andrew M. Steane",
        "Alexei Kitaev"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the conceptual route by which fragile quantum systems can in principle support reliable computation.",
        "attribution": "Shor, Steane, and Kitaev each made distinct foundational contributions to codes and fault-tolerant architectures.",
        "maturity": "The theory is firmly established and experimental demonstrations are increasingly persuasive, although large-scale fault tolerance remains ahead.",
        "uncertainties": [
          "Whether present experimental progress is sufficient to regard fault-tolerant computation as fully established."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped-ion quantum computing transformed a clean atomic system into a highly controllable processor and a laboratory for quantum information.",
        "attribution": "Cirac and Zoller established central theoretical proposals, while Blatt delivered sustained leading experimental realization.",
        "maturity": "The platform has achieved high-fidelity control and independent replication over decades.",
        "uncertainties": [
          "Credit must distinguish foundational trapped-ion computing from the broader quantum-information enterprise."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Jean Dalibard",
        "Markus Greiner"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice quantum simulation has made strongly interacting many-body Hamiltonians experimentally programmable and observable.",
        "attribution": "Bloch, Dalibard, and Greiner represent major and complementary experimental leadership in establishing the field.",
        "maturity": "The approach is mature, widely reproduced, and has yielded clean observations inaccessible in ordinary solids.",
        "uncertainties": [
          "The foundational theoretical and experimental credit is unusually broad."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade turned strong neutral-atom interactions into a powerful controllable many-body and computing platform.",
        "attribution": "Saffman and Lukin made key conceptual contributions, and Browaeys has been central to definitive programmable-array experiments.",
        "maturity": "Large arrays and coherent control are now compelling and replicated, though the computing promise is still developing.",
        "uncertainties": [
          "It remains uncertain whether the eventual fundamental legacy will be quantum simulation, computing, or both."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B034",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent optical detection and control of individual nitrogen-vacancy spins created an unusually practical bridge between quantum coherence and nanoscale sensing.",
        "attribution": "Jelezko and Wrachtrup were central to establishing single-defect optical spin control and its physical consequences.",
        "maturity": "The phenomena are robust, extensively reproduced, and broadly used in quantum sensing.",
        "uncertainties": [
          "The extent to which the advance should be rewarded as fundamental physics rather than an enabling measurement technology."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg",
        "Andrew N. Cleland"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics and quantum acoustics brought engineered mechanical motion into the quantum regime and enabled striking tests of measurement and control.",
        "attribution": "Aspelmeyer, Kippenberg, and Cleland made major complementary contributions spanning cavity optomechanics and quantum mechanical devices.",
        "maturity": "Quantum control of mechanical systems is experimentally secure across several architectures.",
        "uncertainties": [
          "The discovery boundary between optomechanics, quantum acoustics, and related electromechanical work is broad."
        ]
      }
    }
  ]
}
